```iec-st
FUNCTION_BLOCK FB_FloatGlass_TinElectromagneticStirrer
(*
====================================================================================================
PROJECT:        Lumina Advanced Cyber-Physical Industrial Automation Platform
SYSTEM:         Float Glass Manufacturing Line - Pilkington Float Bath Section
SUBSYSTEM:      Molten Tin Bath Linear Induction Stirrer (LIS/EMS) & Dross Scum Skimming Controller
ENGINEER:       Principal Automation Fellow & Cyber-Physical Systems Chair
IEC 61131-3:    Structured Text (ST) Deterministic Function Block
COMPLIANCE:     IEC 61508 SIL-2 / IEC 61131-3 3rd Ed. / ISA-88 Batch & Continuous Process
====================================================================================================
DESCRIPTION:
    Implements multi-physics cyber-physical regulation of a Linear Induction Stirrer (LIS)
    and an automated mechanical dross scum skimming system in a float glass tin bath.

    1. Electromagnetic Modeling:
       - Multi-phase traveling magnetic field: B(x,t) = B0 * sin(omega*t - k*x)
       - Slip calculation: s = (Vs - V_tin) / Vs, where Vs = 2 * Tau_p * f
       - Dimensionless Magnetic Reynolds number: Rm = Mu0 * Sigma * Vs * Tau_p / Pi
       - Lorentz volumetric force density: F_x = 0.5 * Sigma * s * Vs * B0^2 / (1 + (s * Rm)^2)
       - Dynamic compensation for bath temperature-dependent electrical conductivity of liquid tin

    2. Fault-Tolerant Sensing:
       - Triple Modular Redundancy (2oo3 TMR) voting on molten tin liquid surface level radar gauges
       - Dynamic tolerance windowing, channel discrepancy isolation, and graceful 2oo2 degradation

    3. Advanced Multivariable Control:
       - Discrete State-Space Model (3x3) governing surface flow velocity, return back-eddy,
         and boundary layer shear stress adjacent to the fragile float glass ribbon
       - Model Predictive Control (MPC) quadratic cost optimization with acceleration limits
         to eliminate Faraday surface standing waves and glass ribbon optical distortion

    4. Dross Scum Skimming Automation:
       - Automated detection of surface stannous/stannic oxide (SnO, SnO2) dross formation
       - Synchronized 4-stage pneumatic blade immersion, linear carriage traverse sweep,
         weir deposit into collection dross pocket, and rapid return cycle

    5. Graceful Degradation & Safety Architecture:
       - Hierarchical 32-bit alarm tree with automated thermal derating of stator excitation
       - Emergency dry Nitrogen (N2) atmosphere flood upon trace Oxygen (O2) breakthrough
====================================================================================================
*)

VAR_INPUT
    bSystemEnable               : BOOL;     (* Master supervisory run command from Line DCS *)
    bEmergencyHalt              : BOOL;     (* Safety relay fail-safe loop status (Active LOW: 0=Trip) *)
    bManualSkimCommand          : BOOL;     (* Operator manual dross skimming initiation pulse *)
    bResetFaults                : BOOL;     (* Fault and alarm acknowledge/reset pushbutton *)

    (* Molten Tin Bath Thermodynamics and Kinetics *)
    rTinBathTemp_ZoneA          : REAL;     (* Canal entrance wet-back zone temperature [deg C] *)
    rTinBathTemp_ZoneB          : REAL;     (* Center waist bath zone temperature [deg C] *)
    rTinBathTemp_ZoneC          : REAL;     (* Exit lehr transition zone temperature [deg C] *)

    (* Triple Modular Redundancy (2oo3) Tin Level Radar Sensors *)
    rTinLevel_TMR_Ch1           : REAL;     (* Contactless radar molten tin surface level Ch1 [mm] *)
    rTinLevel_TMR_Ch2           : REAL;     (* Contactless radar molten tin surface level Ch2 [mm] *)
    rTinLevel_TMR_Ch3           : REAL;     (* Contactless radar molten tin surface level Ch3 [mm] *)

    (* Float Glass Ribbon Dynamics *)
    rGlassRibbonSpeed           : REAL;     (* Annealing lehr pull roll linear velocity [m/min] *)
    rGlassRibbonThickness       : REAL;     (* Optical gauge calibrated ribbon thickness [mm] *)
    rGlassRibbonWidth           : REAL;     (* Overhead optical width measurement [m] *)

    (* Linear Induction Motor (LIM/EMS) Feedback *)
    rStirrerCurrent_U           : REAL;     (* Phase U primary stator rms current [A] *)
    rStirrerCurrent_V           : REAL;     (* Phase V primary stator rms current [A] *)
    rStirrerCurrent_W           : REAL;     (* Phase W primary stator rms current [A] *)
    rVFD_FrequencyFeedback      : REAL;     (* Inverter output traveling field excitation frequency [Hz] *)
    rStatorCoreTemp_1           : REAL;     (* Embedded PT100 RTD sensor - Stator Core Inboard [deg C] *)
    rStatorCoreTemp_2           : REAL;     (* Embedded PT100 RTD sensor - Stator Core Outboard [deg C] *)
    rCoolingWaterFlow_LPM       : REAL;     (* Demineralized closed-loop stator cooling flow [L/min] *)

    (* Atmosphere & Chemistry Monitoring *)
    rAtmosphere_H2_Conc         : REAL;     (* Reducing atmosphere Hydrogen fraction [%] *)
    rAtmosphere_O2_Trace        : REAL;     (* Trace oxygen contaminant concentration [ppm] *)

    (* Dross Detection and Skimmer Kinematics *)
    rDrossScumLayerHeight       : REAL;     (* Optical laser triangulation dross scum depth [mm] *)
    rSkimmerPocketLevel         : REAL;     (* Side extraction pocket dross accumulation capacity [%] *)
    rSkimmerCarriagePosition    : REAL;     (* Linear absolute encoder carriage position [mm] *)

    (* Execution Environment *)
    tScanCycleTime              : TIME;     (* Deterministic PLC task cycle delta [ms] *)
END_VAR

VAR_OUTPUT
    bSystemReady                : BOOL;     (* Subsystem fully initialized and interlocked *)
    bStirrerVFD_RunPermissive   : BOOL;     (* Hardwired enable contactor drive to LIS VFD *)
    bSkimmerMotorForward        : BOOL;     (* Linear actuator forward sweep stroke command *)
    bSkimmerMotorReverse        : BOOL;     (* Linear actuator return home stroke command *)
    bSkimmerBladeDown           : BOOL;     (* Pneumatic cylinder lower skimming weir blade *)
    bEmergencyN2PurgeValve      : BOOL;     (* High-velocity dry nitrogen flood solenoid *)

    wSystemStatusWord           : WORD;     (* Hex packed operational state status *)
    dwAlarmStatusWord           : DWORD;    (* Packed 32-point alarm matrix bitfield *)
    iDegradedModeLevel          : INT;      (* Graceful degradation level: 0=Nominal, 1=Sensor, 2=Derated, 3=Fault *)

    rVFD_FrequencySetpoint      : REAL;     (* Commanded VFD excitation frequency setpoint [Hz] *)
    rVFD_CurrentLimitSetpoint   : REAL;     (* Dynamic stator phase current limit [A] *)
    rCalculatedLorentzThrust_N  : REAL;     (* Estimated electromagnetic volumetric Lorentz thrust [N] *)
    rTinSurfaceVelocity_MPS     : REAL;     (* MPC state-space observer tin surface velocity [m/s] *)
    rSkimmerVelocitySetpoint    : REAL;     (* Commanded skimmer linear drive velocity [mm/s] *)
    rDrossRemovalRate_KGH       : REAL;     (* Estimated mass removal rate of SnO/SnO2 scum [kg/h] *)
    rTinLevelVoted_MM           : REAL;     (* Validated 2oo3 TMR tin surface level datum [mm] *)
END_VAR

VAR
    (* Internal State Machine Configuration *)
    iOperatingState             : INT := 0; (* 0:IDLE, 10:PURGE, 20:PRE_MAG, 30:RAMP, 40:MPC_RUN, 50:SKIM, 60:DERATED, 80:HALT, 99:FAULT *)
    iPreviousState              : INT := 0;
    iSkimmerSubState            : INT := 0; (* Sub-state machine for multi-axis skimming stroke *)

    (* 2oo3 TMR Voting Algorithm Variables *)
    bTMR_Ch1_Valid              : BOOL;
    bTMR_Ch2_Valid              : BOOL;
    bTMR_Ch3_Valid              : BOOL;
    rDiff12                     : REAL;
    rDiff23                     : REAL;
    rDiff31                     : REAL;

    (* Linear Induction Stirrer Physical Constant Parameterization *)
    rPolePitch_Tau              : REAL := 0.180;        (* Stator magnetic pole pitch [m] *)
    rTinConductivity_Sigma0     : REAL := 1.85E6;       (* Molten tin electrical conductivity at 900 C [S/m] *)
    rTinTempCoeff_Alpha         : REAL := -0.00085;     (* Conductivity temp coefficient [1/deg C] *)
    rMagneticPermeability_Mu0   : REAL := 1.256637E-6;  (* Vacuum magnetic permeability [H/m] *)
    rEffectiveAirGap_G          : REAL := 0.042;        (* Refractory bottom + tin layer magnetic gap [m] *)

    (* Dynamic Fluid & Electromagnetic Calculated Variables *)
    rActualTinConductivity      : REAL;
    rSyncLinearVelocity_Vs      : REAL;                 (* Traveling magnetic wave synchronous velocity [m/s] *)
    rSlipRatio_s                : REAL;                 (* Electromagnetic induction slip factor *)
    rMagneticReynoldsNumber     : REAL;                 (* Dimensionless magnetic Reynolds number *)
    rEffectiveFluxDensity_B0    : REAL;                 (* Airgap magnetic flux peak density [Tesla] *)
    rAverageCurrent             : REAL;
    rCurrentUnbalance           : REAL;

    (* Model Predictive Control (MPC) 3x3 State-Space Matrices *)
    (* States: x[1]=Surface Vel [m/s], x[2]=Return Flow Vel [m/s], x[3]=Boundary Shear [1/s] *)
    rState_x1                   : REAL := 0.0;
    rState_x2                   : REAL := 0.0;
    rState_x3                   : REAL := 0.0;
    rState_x1_Next              : REAL := 0.0;
    rState_x2_Next              : REAL := 0.0;
    rState_x3_Next              : REAL := 0.0;

    (* Discrete State Space Matrix Coefficients (Sample Period Ts = 0.050 s) *)
    rA11 : REAL := 0.9420;  rA12 : REAL := 0.0215;  rA13 : REAL := -0.0084;
    rA21 : REAL := 0.0180;  rA22 : REAL := 0.9650;  rA23 : REAL := 0.0012;
    rA31 : REAL := -0.0350; rA32 : REAL := 0.0045;  rA33 : REAL := 0.8920;

    (* Control Input Coupling Vector B *)
    rB1  : REAL := 0.00285;
    rB2  : REAL := -0.00042;
    rB3  : REAL := 0.00165;

    (* Disturbance Coupling Vector E (Glass Ribbon Drag) *)
    rE1  : REAL := 0.00115;
    rE2  : REAL := 0.00012;
    rE3  : REAL := 0.00480;

    (* MPC Optimization Horizon Variables *)
    rTargetVelocity             : REAL;
    rVelocityTrackingError      : REAL;
    rDeltaControlEffort         : REAL;
    rControlEffortAccumulator   : REAL := 0.0;
    rMaxSurfaceVelocityLimit    : REAL := 0.350;        (* Critical meniscus stability threshold [m/s] *)
    rMaxFlowAcceleration_MPS2  : REAL := 0.015;        (* Wave prevention ramp rate [m/s^2] *)

    (* On-Delay Timers for Sequence Coordination *)
    tonPurgeDwell               : TON;
    tonPreMagDwell              : TON;
    tonSkimSettle               : TON;
    tonDerateCooldown           : TON;
    tonFaultHoldoff             : TON;

    (* Dross Skimming Volumetric Integrator *)
    rSkimAccumulatedMass_KG     : REAL := 0.0;
    rSkimCycleTimer_SEC         : REAL := 0.0;
    rCycleTimeDelta_SEC         : REAL;

    (* First-Order Digital Filter Accumulators *)
    rFilteredZoneATemp          : REAL := 950.0;
    rFilteredH2Conc             : REAL := 5.0;
END_VAR

(* === EXECUTABLE CODE INITIALIZATION & TIME INTEGRATION === *)
rCycleTimeDelta_SEC := TIME_TO_REAL(tScanCycleTime) / 1000.0;
IF (rCycleTimeDelta_SEC <= 0.001) OR (rCycleTimeDelta_SEC >= 1.0) THEN
    rCycleTimeDelta_SEC := 0.050; (* Default deterministic 50ms task scan *)
END_IF;

(* First-order low pass digital filtering on critical thermal & gas sensors *)
rFilteredZoneATemp := rFilteredZoneATemp + 0.12 * (rTinBathTemp_ZoneA - rFilteredZoneATemp);
rFilteredH2Conc    := rFilteredH2Conc + 0.08 * (rAtmosphere_H2_Conc - rFilteredH2Conc);

(* === 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) SENSOR VOTING === *)
bTMR_Ch1_Valid := (rTinLevel_TMR_Ch1 >= 40.0) AND (rTinLevel_TMR_Ch1 <= 120.0);
bTMR_Ch2_Valid := (rTinLevel_TMR_Ch2 >= 40.0) AND (rTinLevel_TMR_Ch2 <= 120.0);
bTMR_Ch3_Valid := (rTinLevel_TMR_Ch3 >= 40.0) AND (rTinLevel_TMR_Ch3 <= 120.0);

rDiff12 := ABS(rTinLevel_TMR_Ch1 - rTinLevel_TMR_Ch2);
rDiff23 := ABS(rTinLevel_TMR_Ch2 - rTinLevel_TMR_Ch3);
rDiff31 := ABS(rTinLevel_TMR_Ch3 - rTinLevel_TMR_Ch1);

IF bTMR_Ch1_Valid AND bTMR_Ch2_Valid AND bTMR_Ch3_Valid THEN
    (* Full 3-channel operational: Pairwise discrepancy voting *)
    IF (rDiff12 <= 2.5) AND (rDiff31 <= 2.5) AND (rDiff23 <= 2.5) THEN
        (* All channels agree tightly - Median / average computation *)
        rTinLevelVoted_MM := (rTinLevel_TMR_Ch1 + rTinLevel_TMR_Ch2 + rTinLevel_TMR_Ch3) / 3.0;
        iDegradedModeLevel := 0; (* Nominal *)
        dwAlarmStatusWord.8 := FALSE; (* Clear TMR degraded warning *)
    ELSIF (rDiff12 <= 2.5) THEN
        (* Ch3 deviated *)
        rTinLevelVoted_MM := (rTinLevel_TMR_Ch1 + rTinLevel_TMR_Ch2) * 0.5;
        iDegradedModeLevel := 1;
        dwAlarmStatusWord.8 := TRUE;
    ELSIF (rDiff31 <= 2.5) THEN
        (* Ch2 deviated *)
        rTinLevelVoted_MM := (rTinLevel_TMR_Ch1 + rTinLevel_TMR_Ch3) * 0.5;
        iDegradedModeLevel := 1;
        dwAlarmStatusWord.8 := TRUE;
    ELSIF (rDiff23 <= 2.5) THEN
        (* Ch1 deviated *)
        rTinLevelVoted_MM := (rTinLevel_TMR_Ch2 + rTinLevel_TMR_Ch3) * 0.5;
        iDegradedModeLevel := 1;
        dwAlarmStatusWord.8 := TRUE;
    ELSE
        (* All three channels diverge > 2.5mm: Common-mode corruption or bath surface wave *)
        rTinLevelVoted_MM := (rTinLevel_TMR_Ch1 + rTinLevel_TMR_Ch2 + rTinLevel_TMR_Ch3) / 3.0;
        dwAlarmStatusWord.5 := TRUE; (* TMR Tri-fault alarm *)
    END_IF;
ELSIF bTMR_Ch1_Valid AND bTMR_Ch2_Valid THEN
    rTinLevelVoted_MM := (rTinLevel_TMR_Ch1 + rTinLevel_TMR_Ch2) * 0.5;
    iDegradedModeLevel := 1;
    dwAlarmStatusWord.8 := TRUE;
ELSIF bTMR_Ch2_Valid AND bTMR_Ch3_Valid THEN
    rTinLevelVoted_MM := (rTinLevel_TMR_Ch2 + rTinLevel_TMR_Ch3) * 0.5;
    iDegradedModeLevel := 1;
    dwAlarmStatusWord.8 := TRUE;
ELSIF bTMR_Ch1_Valid AND bTMR_Ch3_Valid THEN
    rTinLevelVoted_MM := (rTinLevel_TMR_Ch1 + rTinLevel_TMR_Ch3) * 0.5;
    iDegradedModeLevel := 1;
    dwAlarmStatusWord.8 := TRUE;
ELSE
    (* Total TMR sensor loss *)
    rTinLevelVoted_MM := 65.0; (* Fallback nominal datum *)
    dwAlarmStatusWord.5 := TRUE;
END_IF;

(* === COMPREHENSIVE SAFETY INTERLOCK & ALARM MATRIX EVALUATION === *)
dwAlarmStatusWord.0 := NOT bEmergencyHalt;                                        (* E-Stop tripped *)
dwAlarmStatusWord.1 := (rStatorCoreTemp_1 > 135.0) OR (rStatorCoreTemp_2 > 135.0); (* Stator core over-temp *)
dwAlarmStatusWord.2 := (rCoolingWaterFlow_LPM < 25.0);                            (* Low cooling water flow *)
dwAlarmStatusWord.3 := (rAtmosphere_O2_Trace > 35.0);                             (* High O2 trace in bath *)
dwAlarmStatusWord.4 := (rFilteredH2Conc < 2.5);                                   (* Low reducing H2 conc *)
dwAlarmStatusWord.6 := (rTinLevelVoted_MM < 52.0) OR (rTinLevelVoted_MM > 82.0);  (* Tin bath level bounds *)

(* Stator current balanced magnitude check *)
rAverageCurrent := (rStirrerCurrent_U + rStirrerCurrent_V + rStirrerCurrent_W) / 3.0;
IF rAverageCurrent > 10.0 THEN
    rCurrentUnbalance := (MAX(MAX(rStirrerCurrent_U, rStirrerCurrent_V), rStirrerCurrent_W) - 
                          MIN(MIN(rStirrerCurrent_U, rStirrerCurrent_V), rStirrerCurrent_W)) / rAverageCurrent;
    dwAlarmStatusWord.7 := (rCurrentUnbalance > 0.15); (* Current asymmetry > 15% *)
ELSE
    dwAlarmStatusWord.7 := FALSE;
END_IF;

(* Process Warnings *)
dwAlarmStatusWord.10 := (rDrossScumLayerHeight >= 3.5);     (* Dross accumulation high *)
dwAlarmStatusWord.14 := (rSkimmerPocketLevel >= 90.0);      (* Dross trap collector bin full *)

(* Evaluate emergency atmosphere protection *)
bEmergencyN2PurgeValve := dwAlarmStatusWord.3 OR dwAlarmStatusWord.4;

(* Trip Interlock Check: Any critical alarm trips system to State 99 *)
IF dwAlarmStatusWord.0 OR dwAlarmStatusWord.1 OR dwAlarmStatusWord.2 OR dwAlarmStatusWord.6 OR dwAlarmStatusWord.7 THEN
    iOperatingState := 99; (* EMERGENCY TRIP & SAFE SHUTDOWN *)
END_IF;

(* === ELECTROMAGNETIC FIELD & LORENTZ THRUST KINEMATICS === *)
(* Temperature compensated molten tin electrical conductivity *)
rActualTinConductivity := rTinConductivity_Sigma0 * (1.0 + rTinTempCoeff_Alpha * (rFilteredZoneATemp - 900.0));
IF rActualTinConductivity < 1.0E6 THEN
    rActualTinConductivity := 1.0E6; (* Saturation floor *)
END_IF;

(* Synchronous traveling wave velocity: Vs = 2 * Tau * f *)
rSyncLinearVelocity_Vs := 2.0 * rPolePitch_Tau * MAX(rVFD_FrequencyFeedback, 0.5);

(* Slip calculation relative to current surface flow velocity *)
IF rSyncLinearVelocity_Vs > 0.05 THEN
    rSlipRatio_s := (rSyncLinearVelocity_Vs - rTinSurfaceVelocity_MPS) / rSyncLinearVelocity_Vs;
ELSE
    rSlipRatio_s := 1.0;
END_IF;

(* Air gap flux density approximation: B0 proportional to stator current / airgap *)
rEffectiveFluxDensity_B0 := (rAverageCurrent * 0.0032) / MAX(rEffectiveAirGap_G, 0.020);

(* Dimensionless magnetic Reynolds number: Rm = Mu0 * Sigma * Vs * Tau / Pi *)
rMagneticReynoldsNumber := (rMagneticPermeability_Mu0 * rActualTinConductivity * rSyncLinearVelocity_Vs * rPolePitch_Tau) / 3.14159265;

(* Net volumetric electromagnetic Lorentz thrust force [N]: F = 0.5 * Sigma * s * Vs * B0^2 / (1 + (s * Rm)^2) *)
rCalculatedLorentzThrust_N := (0.5 * rActualTinConductivity * rSlipRatio_s * rSyncLinearVelocity_Vs * 
                               (rEffectiveFluxDensity_B0 * rEffectiveFluxDensity_B0)) / 
                               (1.0 + (rSlipRatio_s * rMagneticReynoldsNumber * rSlipRatio_s * rMagneticReynoldsNumber));

(* Limit thrust to physical boundaries *)
IF rCalculatedLorentzThrust_N < 0.0 THEN
    rCalculatedLorentzThrust_N := 0.0;
ELSIF rCalculatedLorentzThrust_N > 1250.0 THEN
    rCalculatedLorentzThrust_N := 1250.0;
END_IF;

(* === DISCRETE STATE-SPACE MODEL & MODEL PREDICTIVE OBSERVER === *)
(* Glass ribbon disturbance drag force (speed in m/min converted to m/s, weighted by thickness) *)
rE1 := (rGlassRibbonSpeed / 60.0) * (rGlassRibbonThickness / 4.0) * 0.0018;

(* State update equations: x(k+1) = A*x(k) + B*u(k) + E*d(k) *)
rState_x1_Next := (rA11 * rState_x1) + (rA12 * rState_x2) + (rA13 * rState_x3) + 
                  (rB1 * rControlEffortAccumulator) + rE1;

rState_x2_Next := (rA21 * rState_x1) + (rA22 * rState_x2) + (rA23 * rState_x3) + 
                  (rB2 * rControlEffortAccumulator) + (rE1 * 0.15);

rState_x3_Next := (rA31 * rState_x1) + (rA32 * rState_x2) + (rA33 * rState_x3) + 
                  (rB3 * rControlEffortAccumulator) + (rE1 * 0.45);

(* State rollover with bound limiting *)
rState_x1 := LIMIT(0.0, rState_x1_Next, 0.450);
rState_x2 := LIMIT(-0.250, rState_x2_Next, 0.250);
rState_x3 := LIMIT(-1.50, rState_x3_Next, 1.50);

rTinSurfaceVelocity_MPS := rState_x1;

(* Check surface stability / wave turbulence *)
dwAlarmStatusWord.13 := (rTinSurfaceVelocity_MPS > rMaxSurfaceVelocityLimit) OR (ABS(rState_x3) > 1.10);

(* === MULTI-STAGE AUTOMATION STATE MACHINE === *)
CASE iOperatingState OF

    0: (* STATE_STANDBY_IDLE *)
        bSystemReady                := FALSE;
        bStirrerVFD_RunPermissive   := FALSE;
        rVFD_FrequencySetpoint      := 0.0;
        rVFD_CurrentLimitSetpoint   := 0.0;
        bSkimmerMotorForward        := FALSE;
        bSkimmerMotorReverse        := FALSE;
        bSkimmerBladeDown           := FALSE;
        rSkimmerVelocitySetpoint    := 0.0;
        rControlEffortAccumulator   := 0.0;
        iSkimmerSubState            := 0;

        tonPurgeDwell(IN := FALSE, PT := T#15S);
        tonPreMagDwell(IN := FALSE, PT := T#5S);

        wSystemStatusWord := 16#0001; (* Standby *)

        IF bSystemEnable AND NOT dwAlarmStatusWord.0 AND (iOperatingState <> 99) THEN
            iOperatingState := 10; (* Proceed to atmosphere purge & cooling check *)
        END_IF;

    10: (* STATE_PURGE_ATMOSPHERE_VERIFICATION *)
        wSystemStatusWord := 16#0002;

        (* Verify protective atmosphere and cooling water flow *)
        tonPurgeDwell(IN := (rFilteredH2Conc >= 3.5) AND (rAtmosphere_O2_Trace <= 15.0) AND (rCoolingWaterFlow_LPM >= 28.0),
                      PT := T#15S);

        IF tonPurgeDwell.Q THEN
            tonPurgeDwell(IN := FALSE, PT := T#15S);
            iOperatingState := 20; (* Proceed to pre-magnetization *)
        ELSIF NOT bSystemEnable THEN
            iOperatingState := 0;
        END_IF;

    20: (* STATE_PRE_MAGNETIZATION_TEST *)
        wSystemStatusWord := 16#0004;
        bStirrerVFD_RunPermissive := TRUE;
        rVFD_FrequencySetpoint := 4.5;       (* Low frequency tickler field [Hz] *)
        rVFD_CurrentLimitSetpoint := 25.0;   (* Diagnostic coil test current [A] *)

        tonPreMagDwell(IN := (rAverageCurrent >= 18.0) AND NOT dwAlarmStatusWord.7,
                       PT := T#5S);

        IF tonPreMagDwell.Q THEN
            tonPreMagDwell(IN := FALSE, PT := T#5S);
            iOperatingState := 30; (* Proceed to velocity ramp *)
        ELSIF NOT bSystemEnable THEN
            iOperatingState := 0;
        END_IF;

    30: (* STATE_LORENTZ_ACCELERATION_RAMP *)
        wSystemStatusWord := 16#0008;
        bSystemReady := TRUE;
        bStirrerVFD_RunPermissive := TRUE;

        (* Soft ramp traveling field frequency and current limit *)
        IF rVFD_FrequencySetpoint < 18.0 THEN
            rVFD_FrequencySetpoint := rVFD_FrequencySetpoint + (1.2 * rCycleTimeDelta_SEC);
        ELSE
            rVFD_FrequencySetpoint := 18.0;
        END_IF;

        IF rVFD_CurrentLimitSetpoint < 120.0 THEN
            rVFD_CurrentLimitSetpoint := rVFD_CurrentLimitSetpoint + (8.5 * rCycleTimeDelta_SEC);
        ELSE
            rVFD_CurrentLimitSetpoint := 120.0;
        END_IF;

        rControlEffortAccumulator := rVFD_CurrentLimitSetpoint;

        (* Transition to closed-loop MPC regulation once target baseline velocity reached *)
        IF (rTinSurfaceVelocity_MPS >= 0.120) AND (rVFD_FrequencySetpoint >= 17.5) THEN
            iOperatingState := 40; (* Steady-state MPC regulation *)
        END_IF;

    40: (* STATE_STEADY_STATE_MPC_REGULATION *)
        wSystemStatusWord := 16#0010;
        bSystemReady := TRUE;
        bStirrerVFD_RunPermissive := TRUE;

        (* Optimal surface velocity setpoint based on glass ribbon draw speed *)
        rTargetVelocity := LIMIT(0.120, 0.080 + (rGlassRibbonSpeed * 0.014), 0.280);
        rVelocityTrackingError := rTargetVelocity - rTinSurfaceVelocity_MPS;

        (* Constrained MPC predictive optimization step *)
        rDeltaControlEffort := (rVelocityTrackingError * 42.5) - (rState_x3 * 3.8);
        rDeltaControlEffort := LIMIT(-rMaxFlowAcceleration_MPS2 * 100.0, rDeltaControlEffort, rMaxFlowAcceleration_MPS2 * 100.0);

        rControlEffortAccumulator := LIMIT(40.0, rControlEffortAccumulator + (rDeltaControlEffort * rCycleTimeDelta_SEC), 180.0);

        rVFD_CurrentLimitSetpoint := rControlEffortAccumulator;
        rVFD_FrequencySetpoint := 12.0 + (rTinSurfaceVelocity_MPS * 35.0);

        (* Check thermal derating condition on stator core *)
        IF (rStatorCoreTemp_1 > 115.0) OR (rStatorCoreTemp_2 > 115.0) THEN
            iOperatingState := 60; (* Degraded thermal derate *)
        (* Skimming trigger check: high scum depth or manual command *)
        ELSIF (rDrossScumLayerHeight >= 3.2) OR bManualSkimCommand THEN
            iOperatingState := 50; (* Initiate dross skimming *)
        ELSIF NOT bSystemEnable THEN
            iOperatingState := 80; (* Controlled shutdown *)
        END_IF;

    50: (* STATE_CYCLIC_DROSS_SKIM_ACTIVE *)
        wSystemStatusWord := 16#0020;
        bSystemReady := TRUE;

        (* Sub-state machine for synchronized multi-axis dross skimming *)
        CASE iSkimmerSubState OF
            0: (* Lower skimmer blade into dross surface *)
                bSkimmerBladeDown := TRUE;
                bSkimmerMotorForward := FALSE;
                bSkimmerMotorReverse := FALSE;
                rSkimmerVelocitySetpoint := 0.0;
                tonSkimSettle(IN := TRUE, PT := T#2S);
                IF tonSkimSettle.Q THEN
                    tonSkimSettle(IN := FALSE, PT := T#2S);
                    iSkimmerSubState := 10;
                END_IF;

            10: (* Forward skimming stroke driving scum to dross bay *)
                bSkimmerBladeDown := TRUE;
                bSkimmerMotorForward := TRUE;
                bSkimmerMotorReverse := FALSE;
                rSkimmerVelocitySetpoint := 45.0; (* 45 mm/s skimming traverse *)

                (* Increase localized tin velocity slightly to assist scum channeling *)
                rVFD_FrequencySetpoint := 22.0;
                rVFD_CurrentLimitSetpoint := 150.0;

                (* Mass removal integration: Cross section * stroke * density *)
                rDrossRemovalRate_KGH := 18.5;
                rSkimAccumulatedMass_KG := rSkimAccumulatedMass_KG + (rDrossRemovalRate_KGH / 3600.0 * rCycleTimeDelta_SEC);

                IF rSkimmerCarriagePosition >= 2800.0 THEN (* Full stroke complete at 2.8m *)
                    bSkimmerMotorForward := FALSE;
                    iSkimmerSubState := 20;
                END_IF;

            20: (* Retract blade above meniscus *)
                bSkimmerBladeDown := FALSE;
                bSkimmerMotorForward := FALSE;
                tonSkimSettle(IN := TRUE, PT := T#2S);
                IF tonSkimSettle.Q THEN
                    tonSkimSettle(IN := FALSE, PT := T#2S);
                    iSkimmerSubState := 30;
                END_IF;

            30: (* Reverse fast return to home station *)
                bSkimmerBladeDown := FALSE;
                bSkimmerMotorForward := FALSE;
                bSkimmerMotorReverse := TRUE;
                rSkimmerVelocitySetpoint := 90.0; (* 90 mm/s rapid return *)

                IF rSkimmerCarriagePosition <= 25.0 THEN (* Home proximity achieved *)
                    bSkimmerMotorReverse := FALSE;
                    rSkimmerVelocitySetpoint := 0.0;
                    rDrossRemovalRate_KGH := 0.0;
                    iSkimmerSubState := 0;
                    iOperatingState := 40; (* Return to steady-state MPC regulation *)
                END_IF;
        END_CASE;

    60: (* STATE_DEGRADED_THERMAL_DERATE *)
        wSystemStatusWord := 16#0040;
        iDegradedModeLevel := 2; (* Thermal derated *)
        dwAlarmStatusWord.9 := TRUE;

        (* Clamp stator current limit to 55% nominal to protect winding insulation *)
        rVFD_CurrentLimitSetpoint := 75.0;
        rVFD_FrequencySetpoint := 14.0;

        tonDerateCooldown(IN := (rStatorCoreTemp_1 < 95.0) AND (rStatorCoreTemp_2 < 95.0),
                          PT := T#60S);

        IF tonDerateCooldown.Q THEN
            tonDerateCooldown(IN := FALSE, PT := T#60S);
            dwAlarmStatusWord.9 := FALSE;
            iDegradedModeLevel := 0;
            iOperatingState := 40; (* Recover to nominal regulation *)
        ELSIF NOT bSystemEnable THEN
            iOperatingState := 80;
        END_IF;

    80: (* STATE_CONTROLLED_HALT_AND_DECEL *)
        wSystemStatusWord := 16#0080;
        bSystemReady := FALSE;

        (* Ensure skimmer blade retracted and carriage returned to home *)
        bSkimmerBladeDown := FALSE;
        IF rSkimmerCarriagePosition > 30.0 THEN
            bSkimmerMotorReverse := TRUE;
            rSkimmerVelocitySetpoint := 60.0;
        ELSE
            bSkimmerMotorReverse := FALSE;
            rSkimmerVelocitySetpoint := 0.0;
        END_IF;

        (* Controlled deceleration of traveling magnetic field to prevent back-eddy wave *)
        IF rVFD_FrequencySetpoint > 1.0 THEN
            rVFD_FrequencySetpoint := rVFD_FrequencySetpoint - (2.5 * rCycleTimeDelta_SEC);
        ELSE
            rVFD_FrequencySetpoint := 0.0;
        END_IF;

        IF rVFD_CurrentLimitSetpoint > 5.0 THEN
            rVFD_CurrentLimitSetpoint := rVFD_CurrentLimitSetpoint - (15.0 * rCycleTimeDelta_SEC);
        ELSE
            rVFD_CurrentLimitSetpoint := 0.0;
            bStirrerVFD_RunPermissive := FALSE;
            IF rSkimmerCarriagePosition <= 30.0 THEN
                iOperatingState := 0; (* Returned to Standby *)
            END_IF;
        END_IF;

    99: (* STATE_SAFETY_INTERLOCK_FAULT *)
        wSystemStatusWord           := 16#8000; (* Fault Lockout *)
        bSystemReady                := FALSE;
        bStirrerVFD_RunPermissive   := FALSE;
        rVFD_FrequencySetpoint      := 0.0;
        rVFD_CurrentLimitSetpoint   := 0.0;
        bSkimmerMotorForward        := FALSE;
        bSkimmerMotorReverse        := FALSE;
        bSkimmerBladeDown           := FALSE;
        rSkimmerVelocitySetpoint    := 0.0;
        iDegradedModeLevel          := 3; (* Safety Fault Trip *)

        (* Require explicit manual fault reset and trip condition clear *)
        IF bResetFaults AND NOT dwAlarmStatusWord.0 AND NOT dwAlarmStatusWord.1 AND 
           NOT dwAlarmStatusWord.2 AND NOT dwAlarmStatusWord.6 AND NOT dwAlarmStatusWord.7 THEN
            dwAlarmStatusWord := 16#00000000;
            iOperatingState := 0; (* Reset to Standby *)
        END_IF;

END_CASE;

